  "misconception": {
    "pack_id": null,
    "wrong": "Дельта — одно сплошное тело, и её разрез идёт один раз сверху вниз без повторов.",
    "right": "Осадки сходятся к депоцентру у устья. Разрез внутри него часто повторяется из-за чередования стадий продвижения и отмирания.",
    "claims": ["c1", "c2", "c3"]
  },
  "data_meaning": {
    "inputs": [
      {"text": "Разрезы внутри одного депоцентра: порядок пород снизу вверх.", "claims": ["c2"], "hypothesis": false},
      {"text": "Признаки стадий продвижения и отмирания в разрезе. Правило их распознавания в книге не дано.", "claims": [], "hypothesis": true}
    ],
    "outputs": [
      {"text": "Вывод, что разрез относится к депоцентру у устья крупной реки.", "claims": ["c1"], "hypothesis": true}
    ],
    "breaks": [
      {"text": "Цикл всей дельты и цикл её лопасти по одному разрезу не разделить. В тексте нет признаков различия.", "claims": ["c3"], "hypothesis": false},
      {"text": "В небольших или недолгоживущих дельтах серии депоцентров может не быть.", "claims": ["c4"], "hypothesis": false}
    ]
  },
  "it_analogy": {
    "pack_id": null,
    "analogy": "Депоцентр похож на узкое место сети у одного шлюза: весь трафик сходится туда, и нагрузка собирается рядом (аналогия, гипотеза).",
    "breaks_where": "Осадки не идут по маршрутам и не управляются конфигурацией. Место накопления задают рельеф, течения и устье реки."
  },
  "now_nuance": null,
  "threshold": {
    "is_threshold": true,
    "why": "Повторы в разрезе — след роста и отмирания дельты. Без этого разрез читают как один слой, а не как историю."
  },
  "inefficiency": {
    "inputs": ["Разрезы внутри одного депоцентра (гипотеза: из скважин или обнажений).", "Сведения о том, где у дельты устье крупной реки (гипотеза)."],
    "manual_steps": ["Сравнить разрезы внутри одного депоцентра (гипотеза: по описанию пород).", "Отделить повторы разреза от случайных вариаций (гипотеза)."],
    "judgment_points": ["Повтор ли это цикла или просто смена пород (гипотеза).", "Цикл всей дельты или только лопасти (гипотеза; в главе признаков не дано)."],
    "time": ["Установление границ депоцентра и числа стадий требует нескольких разрезов (гипотеза)."],
    "typical_errors": ["Принять один цикл за всю дельту или наоборот (гипотеза).", "Считать серию депоцентров обязательной для любой дельты. Автор пишет «в различных случаях» и указывает крупные, долгоживущие дельты."]
  },
